agent-task.code:
// 한 줄에 JSON 하나. 인코딩은 Core의 기존 Codable을 그대로 쓴다.
// 앱 → CLI
type AppMessage =
    | { start: InstallerRequest }   // 연결 직후 정확히 한 번. 첫 메시지가 아니면 CLI는 usage 오류로 끝낸다.
    | { cancel: {} };               // 언제든. 두 번 와도 된다.

// CLI → 앱
type CLIMessage = { event: InstallerEvent };  // progress | log | finished | failed
// 마지막 메시지는 반드시 finished 또는 failed. 그 뒤에 CLI가 소켓을 닫는다.
// root가 아닌데 .device 요청이 오면, make와 같은 검사에서 걸린 내용을 failed로 보내고 끝낸다.

imagine function runIPC(socketPath: String) async -> ExitCode {
    requirements(`
        socketPath에 connect하고 첫 줄에서 InstallerRequest를 읽는다.
        .device면 make와 같은 검사(root, 존재, isEligible, isLargeEnough)를 거친다. 확인 질문(--yes 없을 때의 입력)은 없다.
        파이프라인 이벤트를 code#wire 형식으로 흘린다. 별도로 소켓을 계속 읽어서
        cancel 메시지나 EOF가 오면 파이프라인 Task를 cancel한다 (P3).
        ipc 모드에서는 stdout에 아무것도 쓰지 않는다. 사람이 읽을 출력은 stderr로만 보낸다.
        종료 코드는 make/build의 규칙을 따른다.
    `);
    ensure(/* .image 요청 → progress 이벤트가 하나 이상 오고, 마지막이 finished, 종료 코드 0 */);
    ensure(/* 진행 중 cancel 전송 → 마지막 이벤트가 failed(kind: .cancelled), 종료 코드는 make가 SIGINT를 받았을 때와 같다 */);
    ensure(/* 진행 중 앱 쪽 소켓을 닫음 → CLI가 정리 후 종료한다. SIGPIPE로 죽지 않는다 (종료 시그널이 아니라 종료 코드로 끝난다) */);
    ensure(/* 첫 메시지가 start가 아님 → failed 또는 usage 종료, 대상은 건드리지 않는다 */);
    ensure(/* root 아님 + .device 요청 → failed(kind: .rootRequired), 장치를 열지 않는다 */);
    ensure(/* 존재하지 않는 소켓 경로 → 0이 아닌 종료 코드, 아무것도 열지 않는다 */);
}

// HelperClient 자리. InstallerViewModel이 보는 표면(onEvent, onDisconnect, start, cancel)은 최대한 유지한다.
@MainActor
imagine class InstallerRunner {
    var onEvent: ((InstallerEvent) -> Void)?
    var onEnded: ((EndReason) -> Void)?   // authCancelled | lost(String) | osascriptFailed(String)

    imagine func start(_ request: InstallerRequest, prompt: String) async throws {
        requirements(`
            1. 0700 임시 디렉토리를 만들고 소켓을 bind/listen한다. 경로가 sun_path(104바이트)를 넘으면 시작하기 전에 실패한다.
            2. code#osascript를 Process로 실행한다. 이 시점에 관리자 대화상자가 뜬다.
            3. accept와 osascript 종료를 경쟁시킨다. osascript가 먼저 끝나면 P5대로 처리한다.
            4. accept되면 start 메시지를 보내고, 이벤트를 onEvent로 넘긴다.
            5. 종결 이벤트, EOF, osascript 종료가 오면 소켓과 임시 디렉토리를 치운다.
        `);
        ensure(/* 인증 대화상자에서 취소 → onEnded(.authCancelled), 임시 디렉토리가 남지 않는다 */);
    }

    imagine func cancel() { requirements(`cancel 메시지를 보낸다. 이미 끝난 연결이면 아무것도 하지 않는다. SIGPIPE로 앱이 죽지 않는다.`); }
}
